import {BASELINE,parseTracksCsv,validateDataset,validateParameters,predictTrack,exportCalibration,toTracksCsv} from './calibration-engine.js';

export function initCalibration({onApply=()=>{}}={}){
  const $=id=>document.getElementById(id);
  let dataset=null,report=null,worker=null,generation=0,busy=false;
  const numeric=x=>Number.isFinite(x)?(x*1000).toFixed(1)+' mm':'—';
  function error(message=''){$('cal-error').textContent=message;$('cal-error').hidden=!message;}
  function baseline(){
    if(!$('cal-base-mu').value.trim()||!$('cal-base-mass').value.trim())throw Error('Enter both starting-model values.');
    return validateParameters({mu:Number($('cal-base-mu').value),mass:Number($('cal-base-mass').value)});
  }
  function canApply(){return report?.identification.identifiable&&report.validation.improved&&!report.diagnostics.some(d=>['validation-gap','lateral-motion'].includes(d.code));}
  function buttons(){
    let valid=true;try{baseline();}catch{valid=false;}
    for(const id of ['cal-load','cal-sample','cal-file','cal-base-mu','cal-base-mass'])$(id).disabled=busy;
    const sample=dataset?.source==='synthetic-mujoco';
    $('cal-source').disabled=busy||sample;$('cal-confirm').disabled=busy||sample;
    $('cal-fit').disabled=busy||!dataset||!$('cal-confirm').checked||!valid;
    $('cal-cancel').hidden=!busy;
    $('cal-export').disabled=busy||!report;$('cal-export-tracks').disabled=busy||!dataset||!report;
    $('cal-apply').disabled=busy||!canApply();
  }
  function clearReport(){report=null;$('cal-results').hidden=true;buttons();}
  function cancel(message){generation++;worker?.terminate();worker=null;busy=false;clearReport();if(message)$('cal-status').textContent=message;buttons();}
  function receipt(){
    if(!dataset){$('cal-data-title').textContent='Start with an example or a CSV.';$('cal-source-tag').textContent='NO DATA';$('cal-data-summary').textContent='The fit uses calibration trials only. Validation rows stay out of the parameter search.';
      $('cal-training-count').textContent='— calibration trials';$('cal-validation-count').textContent='— validation trials';$('cal-row-count').textContent='— samples';$('cal-source-note').textContent='A source label is a declaration. It does not verify a physical experiment.';return;}
    const synthetic=dataset.source==='synthetic-mujoco',declared=dataset.source==='declared-physical';
    $('cal-data-title').textContent=synthetic?'Simulated contact tracks loaded.':'External tracks loaded with new labels.';
    $('cal-source-tag').textContent=synthetic?'SIMULATED INPUT':declared?'DECLARED PHYSICAL / UNVERIFIED':'EXTERNAL / UNVERIFIED';
    $('cal-data-summary').textContent=synthetic?'These measurements were generated by MuJoCo with position noise. No physical robot was used.':'The file source has not been independently verified. Original trial labels and file names are excluded from reports.';
    $('cal-training-count').textContent=dataset.trials.filter(t=>t.split==='calibration').length+' calibration trials';
    $('cal-validation-count').textContent=dataset.trials.filter(t=>t.split==='validation').length+' validation trials';
    $('cal-row-count').textContent=dataset.trials.reduce((s,t)=>s+t.samples.length,0)+' samples';
    $('cal-source-note').textContent=synthetic?'The sample source is locked as simulated input.':'A source label is a declaration. It does not verify a physical experiment.';
  }
  function loaded(value){
    dataset=validateDataset(value);report=null;busy=false;$('cal-confirm').checked=dataset.source==='synthetic-mujoco';
    receipt();clearReport();try{baseline();error();}catch(e){error(e.message);}$('cal-status').textContent='Split ready. Only calibration trials will select the fitted parameters.';buttons();
  }
  $('cal-load').addEventListener('click',async()=>{
    cancel();error();dataset=null;receipt();const token=++generation;busy=true;buttons();$('cal-status').textContent='Loading a simulated capture...';
    try{const response=await fetch('calibration-'+$('cal-sample').value+'.json');if(!response.ok)throw Error('Could not load the sample. Try again.');
      const capture=await response.json();if(token!==generation)return;
      if(capture.schema!=='robot-physics-capture-v1'||capture.source!=='synthetic-mujoco'||capture.dataset?.source!=='synthetic-mujoco')throw Error('Unsupported sample source.');
      loaded(capture.dataset);
    }catch(e){if(token===generation){error(e.message);busy=false;$('cal-status').textContent='No dataset loaded.';buttons();}}
  });
  $('cal-sample').addEventListener('change',()=>{
    cancel();dataset=null;$('cal-confirm').checked=false;error();receipt();buttons();
    $('cal-status').textContent='Example changed. Load its tracks before fitting.';
  });
  async function fileText(file){if(typeof file.text==='function')return file.text();return new Promise((resolve,reject)=>{const reader=new window.FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read the file.'));reader.readAsText(file);});}
  $('cal-file').addEventListener('change',async()=>{
    const file=$('cal-file').files?.[0];if(!file)return;
    cancel();error();dataset=null;receipt();const token=++generation;busy=true;buttons();$('cal-status').textContent='Reading CSV locally...';
    try{if(file.size>2000000)throw Error('Use a CSV smaller than 2 MB.');const text=await fileText(file);if(token!==generation)return;
      $('cal-source').value='external-unverified';loaded(parseTracksCsv(text,'external-unverified'));
    }catch(e){if(token===generation){error(e.message);busy=false;$('cal-status').textContent='No dataset loaded. Fix the CSV and import it again.';buttons();}}
    finally{$('cal-file').value='';}
  });
  function changed(){cancel();try{baseline();error();}catch(e){error(e.message);}if(dataset)$('cal-status').textContent='Settings changed. Fit again to refresh the report.';buttons();}
  for(const id of ['cal-base-mu','cal-base-mass'])$(id).addEventListener('input',changed);
  $('cal-confirm').addEventListener('change',changed);
  $('cal-source').addEventListener('change',()=>{if(dataset&&dataset.source!=='synthetic-mujoco')dataset=validateDataset({...dataset,source:$('cal-source').value});changed();receipt();});
  $('cal-fit').addEventListener('click',()=>{
    cancel();error();
    try{
      const base=baseline();if(!dataset||!$('cal-confirm').checked)throw Error('Load data and confirm the measurement assumptions.');
      busy=true;buttons();$('cal-status').textContent='Fitting calibration trials. Validation positions are excluded from the search.';
      const current=new Worker(new URL('./calibration-worker.js',import.meta.url),{type:'module'});worker=current;
      current.onmessage=event=>{
        if(worker!==current)return;const value=event.data;
        if(value.type==='error'){cancel();error(value.message);$('cal-status').textContent='Fit failed. No report was kept.';return;}
        if(value.type==='complete'){
          worker.terminate();worker=null;busy=false;report=value.report;
          if(report.schema!=='robot-physics-calibration-v1'||report.source!==dataset.source){clearReport();error('The fit returned an invalid report.');return;}
          renderReport();$('cal-status').textContent=dataset.source==='synthetic-mujoco'?'Finished on simulated input. Real-world validation is still pending.':'Fit and held-out check complete. The input source remains unverified.';buttons();
        }
      };
      current.onerror=()=>{if(worker===current){cancel();error('The fit worker could not run. Try again.');}};
      current.postMessage({dataset,baseline:base,confirmed:true});
    }catch(e){cancel();error(e.message);}
  });
  $('cal-cancel').addEventListener('click',()=>cancel('Fit cancelled. Tracks remain available; no fitted report is kept.'));
  $('cal-reset').addEventListener('click',()=>{cancel();dataset=null;$('cal-file').value='';$('cal-confirm').checked=false;$('cal-source').value='external-unverified';$('cal-base-mu').value=BASELINE.mu;$('cal-base-mass').value=BASELINE.mass;error();receipt();buttons();$('cal-status').textContent='Session cleared. Load a dataset to inspect its split.';});
  function renderReport(){
    $('cal-results').hidden=false;
    $('cal-before').textContent=numeric(report.before.validation.rmse);$('cal-after').textContent=numeric(report.after.validation.rmse);
    const reduction=report.validation.relativeReduction;
    $('cal-change').textContent=reduction===null?'No baseline':Math.abs(reduction*100).toFixed(1)+'% '+(reduction>=0?'lower':'higher');
    $('cal-change').dataset.better=String(report.validation.improved);$('cal-change-note').textContent=report.validation.trialsImproved+' / '+report.search.validationTrials+' validation trials improved';
    $('cal-model-title').textContent=report.identification.identifiable?'Candidate physical parameters':'Parameters are not well identified';
    $('cal-fit-mu').textContent=report.identification.identifiable?report.parameters.mu.toFixed(3):'Unclear';
    $('cal-fit-mass').textContent=report.identification.identifiable?report.parameters.mass.toFixed(2)+' kg':'Unclear';
    $('cal-model-note').textContent='Calibration trials select these values. Parameter ranges, contact assumptions, and calibrated force are part of the model. No confidence interval is claimed.';
    $('cal-diagnostics').replaceChildren();
    const messages=report.diagnostics.length?report.diagnostics:[{message:'Held-out error improved and local parameter sensitivity is usable. This finding applies to this dataset; real-world verification is still pending.',positive:true}];
    for(const d of messages){const el=document.createElement('p');el.className='cal-diagnostic'+(d.positive?' positive':'');el.textContent=d.message;$('cal-diagnostics').append(el);}
    $('cal-trial').replaceChildren();
    for(const t of dataset.trials){const option=document.createElement('option');option.value=t.id;option.textContent=t.id+' / '+t.split;$('cal-trial').append(option);}
    $('cal-trial').value=dataset.trials.find(t=>t.split==='validation').id;
    const metrics=[['Calibration RMSE',report.before.calibration.rmse,report.after.calibration.rmse],['Validation end error',report.before.validation.meanEndError,report.after.validation.meanEndError],['Worst validation trial',report.before.validation.worstTrialRmse,report.after.validation.worstTrialRmse],['Validation lateral error',report.before.validation.lateralRmse,report.after.validation.lateralRmse]];
    $('cal-audit-table').innerHTML=metrics.map(([name,b,a])=>'<tr><td>'+name+'</td><td>'+numeric(b)+'</td><td>'+numeric(a)+'</td></tr>').join('');
    $('cal-identification').textContent='Local sensitivity condition: '+(report.identification.condition===null?'undefined':report.identification.condition.toFixed(1))+'. No validation rows were used for fitting. The gain rule is not a significance test.';
    draw();buttons();
  }
  function canvas(id){const el=$(id),box=el.getBoundingClientRect();if(box.width<1||box.height<1)return null;const ratio=Math.min(2,window.devicePixelRatio||1);el.width=Math.round(box.width*ratio);el.height=Math.round(box.height*ratio);const ctx=el.getContext('2d');if(!ctx)return null;ctx.setTransform(ratio,0,0,ratio,0,0);return {ctx,w:box.width,h:box.height};}
  function drawTrack(){
    const cv=canvas('cal-track');if(!cv||!report||!dataset)return;
    const {ctx,w,h}=cv,t=dataset.trials.find(t=>t.id===$('cal-trial').value);if(!t)return;
    const before=predictTrack(report.baseline,t),after=predictTrack(report.parameters,t),start=t.samples[0];
    const projected=p=>(p.x-start.x)*t.command.ux+(p.y-start.y)*t.command.uy;
    const observed=t.samples.map(p=>({t:p.t,d:projected(p)}));
    const b=before.map(p=>({t:p.t,d:projected(p)})),a=after.map(p=>({t:p.t,d:projected(p)}));
    const left=57,right=w-23,top=30,bottom=h-43,maxT=t.samples.at(-1).t;
    const values=[...observed,...b,...a].map(p=>p.d),minY=Math.min(-.003,...values),maxY=Math.max(.012,...values)*1.12;
    const X=x=>left+x/maxT*(right-left),Y=y=>bottom-(y-minY)/(maxY-minY)*(bottom-top);
    ctx.fillStyle='#9ee7d708';ctx.fillRect(left,top,X(t.command.duration)-left,bottom-top);
    ctx.font='9px system-ui,sans-serif';ctx.fillStyle='#7999ac';ctx.textAlign='left';ctx.fillText('TRAVEL ALONG PUSH / CM',left,17);
    for(let i=0;i<=4;i++){const y=minY+(maxY-minY)*i/4;ctx.beginPath();ctx.moveTo(left,Y(y));ctx.lineTo(right,Y(y));ctx.strokeStyle='#263947';ctx.lineWidth=.7;ctx.stroke();ctx.textAlign='right';ctx.fillStyle='#7899ad';ctx.fillText((100*y).toFixed(1),left-9,Y(y)+3);}
    for(let i=0;i<=4;i++){const time=maxT*i/4;ctx.textAlign='center';ctx.fillText(time.toFixed(2),X(time),bottom+19);}
    ctx.textAlign='right';ctx.fillText('seconds',right,bottom+33);
    ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(X(t.command.duration),top);ctx.lineTo(X(t.command.duration),bottom);ctx.strokeStyle='#557366';ctx.stroke();ctx.setLineDash([]);
    function curve(points,color,dash){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(X(p.t),Y(p.d)):ctx.moveTo(X(p.t),Y(p.d)));ctx.strokeStyle=color;ctx.lineWidth=1.8;ctx.setLineDash(dash);ctx.stroke();ctx.setLineDash([]);}
    curve(b,'#83b9ef',[5,4]);curve(a,'#9ee7d7',[]);
    ctx.fillStyle='#f3ad72';for(const p of observed){ctx.beginPath();ctx.arc(X(p.t),Y(p.d),2,0,Math.PI*2);ctx.fill();}
    const m=report.trials.find(x=>x.id===t.id);
    $('cal-track-note').textContent=t.split.toUpperCase()+' / '+t.command.force.toFixed(1)+' N for '+t.command.duration.toFixed(3)+' s. Two-dimensional trial RMSE: '+numeric(m.beforeRmse)+' → '+numeric(m.afterRmse)+'. The chart projects travel; the metrics also count off-axis error.';
  }
  function drawLandscape(){
    const cv=canvas('cal-landscape');if(!cv||!report)return;
    const {ctx,w,h}=cv,left=42,right=w-20,top=12,bottom=h-31,cw=(right-left)/13,ch=(bottom-top)/19;
    const lo=Math.min(...report.landscape.map(x=>x.rmse)),hi=Math.max(...report.landscape.map(x=>x.rmse));
    report.landscape.forEach((p,i)=>{const v=1-Math.log1p((p.rmse-lo)*100)/Math.max(1e-8,Math.log1p((hi-lo)*100));ctx.fillStyle=`rgb(${Math.round(24+115*v)},${Math.round(43+160*v)},${Math.round(60+118*v)})`;ctx.fillRect(left+i%13*cw,top+(18-Math.floor(i/13))*ch,cw+.1,ch+.1);});
    ctx.strokeStyle='#486577';ctx.strokeRect(left,top,right-left,bottom-top);ctx.fillStyle='#8ba9ba';ctx.font='9px Consolas,monospace';ctx.textAlign='right';ctx.fillText('0.62',left-6,top+7);ctx.fillText('0.08',left-6,bottom);ctx.fillText('μ',left-8,(top+bottom)/2);
    ctx.textAlign='center';ctx.fillText('0.35 kg',left+18,bottom+18);ctx.fillText('1.55 kg',right-18,bottom+18);
    const x=left+(report.parameters.mass-.35)/1.2*(right-left),y=bottom-(report.parameters.mu-.08)/.54*(bottom-top);ctx.strokeStyle='#effff7';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(x-5,y);ctx.lineTo(x+5,y);ctx.moveTo(x,y-5);ctx.lineTo(x,y+5);ctx.stroke();
  }
  function draw(){if(report&&!$('calibrate-page').hidden){drawTrack();drawLandscape();}}
  $('cal-trial').addEventListener('change',drawTrack);
  new ResizeObserver(draw).observe($('cal-track'));window.addEventListener('hashchange',()=>requestAnimationFrame(draw));
  function download(name,value,type){const url=URL.createObjectURL(new Blob([value],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  $('cal-export').addEventListener('click',()=>{if(report)download('physics-calibration-report.json',JSON.stringify(exportCalibration(report),null,2),'application/json');});
  $('cal-export-tracks').addEventListener('click',()=>{if(dataset&&report)download('physics-tracks.csv',toTracksCsv(dataset),'text/csv');});
  $('cal-apply').addEventListener('click',()=>{if(canApply()){onApply({mu:report.parameters.mu,mass:report.parameters.mass});location.hash='experiment';}});
  buttons();
}
